sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 screenColor;
uniform float autoSample;
uniform float invert;
uniform float threshold;
uniform float softness;
uniform float spill;
uniform float blackClip;
uniform float whiteClip;
uniform float feather;
uniform float despill;
uniform float keyMix;
uniform float macroPixels;
uniform float pixelShape;
uniform float pixelGap;
uniform float subpixel;
uniform float pixelGlow;
uniform float cameraZoom;
uniform float2 target;
uniform float2 focusPoint;
uniform float tiltX;
uniform float tiltY;
uniform float roll;
uniform float dof;
uniform float focusDepth;
uniform float focusRange;
uniform float depthFromLuma;
uniform float animateTarget;
uniform float targetSpeed;
uniform float targetRange;
uniform float animateAngle;
uniform float angleSpeed;
uniform float angleRange;
uniform float animateFocus;
uniform float focusSpeed;
uniform float focusTravel;
uniform float autoZoom;
uniform float autoExposure;
uniform float exposure;
layout(color) uniform half4 tintColor;
uniform float tintAmount;
uniform float vignette;
uniform float aberration;
uniform float distortion;
uniform float dust;
uniform float dustSize;
uniform float dustSeed;
uniform float quality;
uniform float sheen;
const float PI = 3.14159265;
float2 rot(float2 p, float a) { float c = cos(a); float s = sin(a); return float2(p.x * c - p.y * s, p.x * s + p.y * c); }
float hash21(float2 p) { p = fract(p * float2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }
half4 sampleSource(float2 uv) { return image.eval(clamp(uv, float2(0.0), float2(1.0)) * size); }
float3 sourceRGB(float2 uv) { return unpremul(sampleSource(uv)).rgb; }
float2 cameraUV(float2 coord, out float2 screenUV, out float2 focusUV) {
    float2 uv = coord / max(size, float2(1.0));
    screenUV = uv;
    float tt = time;
    float2 look = target;
    if (animateTarget > 0.5) look += float2(sin(tt * targetSpeed * 6.283), cos(tt * targetSpeed * 5.117) * 0.55) * targetRange;
    float a = radians(roll + (animateAngle > 0.5 ? sin(tt * angleSpeed * 6.283) * angleRange : 0.0));
    float2 d = rot(uv - look, -a);
    float sx = tan(radians(tiltX));
    float sy = tan(radians(tiltY));
    float2 tilted = d;
    tilted.x += d.y * sx;
    tilted.y += d.x * sy;
    float zoom = clamp(cameraZoom, 0.5, 8.0);
    if (autoZoom > 0.5) {
        float cover = max(abs(look.x - 0.5), abs(look.y - 0.5)) * 2.0;
        zoom = max(zoom, 1.0 / max(0.18, 1.0 - cover * 0.82));
    }
    tilted /= zoom;
    float2 shaped = tilted * (1.0 + distortion * dot(tilted, tilted) * 2.0);
    focusUV = focusPoint;
    if (animateFocus > 0.5) focusUV.x += sin(tt * focusSpeed * 6.283) * focusTravel;
    return look + shaped;
}
float2 chroma(half3 c) { return float2(-0.168736 * c.r - 0.331264 * c.g + 0.5 * c.b, 0.5 * c.r - 0.418688 * c.g - 0.081312 * c.b); }
float matteAt(float2 uv, float2 keyChroma) {
    half4 c = sampleSource(uv);
    if (c.a <= 0.001) return 0.0;
    float d = distance(chroma(unpremul(c).rgb), keyChroma);
    float keep = smoothstep(threshold, threshold + softness + 0.0001, d);
    return invert > 0.5 ? 1.0 - keep : keep;
}
float dustAt(float2 coord, float scale, float seed) {
    if (scale <= 0.0) return 0.0;
    float2 cell = coord / max(scale, 1.0);
    float2 id = floor(cell);
    float h = hash21(id + seed);
    float speck = step(0.996 - dust * 0.012, h);
    float2 f = fract(cell) - 0.5;
    return (1.0 - smoothstep(0.04, 0.32, length(f))) * speck * dust;
}
half4 main(float2 coord) {
    float2 screenUV;
    float2 focusUV;
    float2 p = cameraUV(coord, screenUV, focusUV);
    float3 key = unpremul(sampleSource(p)).rgb;
    float2 keyChroma = chroma(key);
    float focusDist = depthFromLuma > 0.5 ? abs(dot(key, float3(0.2126, 0.7152, 0.0722)) - focusDepth) : distance(p, focusUV);
    float coc = smoothstep(focusRange * 0.45, focusRange * 1.6, focusDist);
    float radius = dof * coc / max(size.x, size.y);
    float2 ca = (screenUV - 0.5) * aberration / max(size, float2(1.0));
    int samples = 1 + int(clamp(quality, 0.0, 3.0)) * 2;
    float3 rgb = float3(0.0);
    float total = 0.0;
    for (int i = 0; i < 7; i++) {
        if (i >= samples) break;
        float ang = float(i) * 2.399963 + 0.5;
        float2 offset = float2(cos(ang), sin(ang)) * radius * (float(i) / 6.0);
        float2 q = p + offset;
        rgb += float3(sourceRGB(q + ca).r, sourceRGB(q).g, sourceRGB(q - ca).b);
        total += 1.0;
    }
    rgb /= max(total, 1.0);
    float2 cellSize = max(float2(macroPixels), float2(1.0));
    float2 cellUV = p * size / cellSize;
    float2 local = fract(cellUV);
    if (macroPixels > 0.5) {
        float2 center = (floor(cellUV) + 0.5) * cellSize / size;
        rgb = float3(sourceRGB(center + ca).r, sourceRGB(center).g, sourceRGB(center - ca).b);
        float aperture = pixelShape > 1.5 ? 1.0 : (pixelShape > 0.5 ? (1.0 - smoothstep(0.5 - pixelGap * 0.5, 0.5, max(abs(local.x - 0.5), abs(local.y - 0.5)))) : (1.0 - smoothstep(0.5 - pixelGap * 0.5, 0.5, length(local - 0.5))));
        if (subpixel > 0.5) {
            float3 stripe = float3(1.0 - smoothstep(0.0, 0.36, abs(local.x - 0.166)), 1.0 - smoothstep(0.0, 0.36, abs(local.x - 0.5)), 1.0 - smoothstep(0.0, 0.36, abs(local.x - 0.833)));
            rgb *= mix(float3(1.0), stripe * 1.7, 0.62);
        }
        rgb *= mix(1.0, aperture, clamp(pixelGap * 1.8, 0.0, 1.0));
        if (pixelGlow > 0.01) {
            float2 left = (floor(cellUV) + float2(-0.5, 0.5)) * cellSize / size;
            float2 right = (floor(cellUV) + float2(1.5, 0.5)) * cellSize / size;
            float2 up = (floor(cellUV) + float2(0.5, -0.5)) * cellSize / size;
            float2 down = (floor(cellUV) + float2(0.5, 1.5)) * cellSize / size;
            float3 glow = (sourceRGB(left) + sourceRGB(right) + sourceRGB(up) + sourceRGB(down)) * 0.25;
            rgb += glow * pixelGlow * 0.28;
        }
    }
    float matte = keyMix > 0.001 ? mix(1.0, matteAt(p, keyChroma), clamp(keyMix, 0.0, 1.0)) : 1.0;
    matte = clamp((matte - blackClip) / max(whiteClip - blackClip, 0.0001), 0.0, 1.0);
    if (feather > 0.01) {
        float r = max(feather, 0.0);
        float sum = matte;
        sum += matteAt(p + float2(r, 0.0) / size, keyChroma);
        sum += matteAt(p - float2(r, 0.0) / size, keyChroma);
        sum += matteAt(p + float2(0.0, r) / size, keyChroma);
        sum += matteAt(p - float2(0.0, r) / size, keyChroma);
        sum += matteAt(p + float2(r, r) * 0.7071 / size, keyChroma);
        sum += matteAt(p - float2(r, r) * 0.7071 / size, keyChroma);
        sum += matteAt(p + float2(r, -r) * 0.7071 / size, keyChroma);
        sum += matteAt(p - float2(r, -r) * 0.7071 / size, keyChroma);
        matte = mix(matte, sum / 9.0, clamp(feather / 12.0, 0.0, 1.0));
    }
    float keyLen = max(dot(key, key), 0.0001);
    float along = dot(rgb, key) / keyLen;
    float neutral = dot(rgb, float3(0.2126, 0.7152, 0.0722));
    float excess = max(along - neutral, 0.0);
    float3 despilled = clamp(rgb - key * excess * despill * spill, 0.0, 1.0);
    rgb = mix(rgb, despilled, clamp(spill + despill, 0.0, 1.0));
    float autoExp = autoExposure > 0.5 ? (0.42 - dot(key, float3(0.2126, 0.7152, 0.0722))) : 0.0;
    rgb *= exp2(exposure + autoExp);
    rgb = mix(rgb, rgb * tintColor.rgb, clamp(tintAmount, 0.0, 1.0));
    float sheenLight = pow(max(0.0, 1.0 - length(screenUV - float2(0.35, 0.2))), 3.0);
    rgb += sheen * sheenLight * 0.12;
    float2 vd = screenUV - 0.5;
    rgb *= 1.0 - vignette * dot(vd, vd) * 2.0;
    rgb += dustAt(coord, dustSize, dustSeed) * 0.65;
    float alpha = sampleSource(p).a * matte;
    return half4(clamp(rgb, 0.0, 1.0) * matte, alpha);
}
